import{_ as e,o as l,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-02-11 :: Ceph Crimson Meeting","description":"","frontmatter":{"title":"2020-02-11 :: Ceph Crimson Meeting","date":"2020-02-11T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","distributed storage","CRUSH algorithm","high availability","scalability","object storage","block storage","file system storage","consistency","decentralization","performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-02-11_-_-_Ceph_Crimson_Meeting.md","filePath":"posts/2020/2020-02-11_-_-_Ceph_Crimson_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-02-11_-_-_Ceph_Crimson_Meeting.md"};function r(n,i,s,h,_,d){return l(),a("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph Crimson会议重点关注了Ceph存储系统的技术问题，包括缓存机制、消息处理、性能优化以及代码实现细节。多位研发人员分享了他们在各自的研发方向上的进展和遇到的问题，并讨论了解决方案和后续行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>缓存机制</strong>：</p><ul><li>讨论了OSD地图处理路径中的缓存策略，特别是两级缓存的存在原因。</li><li>确认了使用增量缓存列表的必要性，以便在不同OSD地图版本间高效传输数据。</li></ul></li><li><p><strong>消息处理与路由</strong>：</p><ul><li>探讨了在Crimson存储系统中实现消息路由的策略，特别是从一对一模型转向多对多模型的可能性。</li><li>讨论了在消息处理中添加PG日志条目对性能的影响，并提出了优化编码效率的建议。</li></ul></li><li><p><strong>性能优化</strong>：</p><ul><li>讨论了如何通过减少内存拷贝来提高本地堆栈的性能，特别是通过启用iommu和设备内存映射。</li><li>分析了pending和dirty状态在事务处理中的区别及其对性能的影响。</li></ul></li><li><p><strong>代码实现与测试</strong>：</p><ul><li>分享了在Crimson中实现PG锁和写路径的进展，以及相关的性能测试结果。</li><li>讨论了如何通过代码审查和测试来确保新功能的稳定性和性能。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>将继续优化缓存机制，尤其是在处理OSD地图和增量数据时的效率。</li><li>将探索从一对一消息模型转向多对多模型的可行性，并评估其对系统性能的影响。</li><li>将进行更多的性能测试，特别是关于内存拷贝和消息编码的优化。</li><li>将通过代码审查和测试来确保新功能的稳定性和性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续研究和优化缓存机制，特别是在处理OSD地图和增量数据时的效率。</li><li>探索从一对一消息模型转向多对多模型的可行性，并评估其对系统性能的影响。</li><li>进行更多的性能测试，特别是关于内存拷贝和消息编码的优化。</li><li>通过代码审查和测试来确保新功能的稳定性和性能。</li><li>创建一个Google文档，用于收集和讨论研发过程中的问题和解决方案，以便团队成员共享知识和经验。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议中提到了一些技术细节和代码实现问题，这些问题将在后续的研发过程中进一步探讨和解决。</li><li>鼓励团队成员在研发过程中保持沟通和协作，共同推动Ceph存储系统的优化和发展。</li></ul>',11)])])}const c=e(o,[["render",r]]);export{u as __pageData,c as default};
